+function svgCreature(s,size=100){const [a,b]=s.colors;let extra='';if(s.shape==='fox')extra=`<path d="M29 43 23 14 43 32M59 32 78 13 73 46" fill="${a}" stroke="#375d4a" stroke-width="3" stroke-linejoin="round"/><path d="m28 22 9 13M73 22 64 35" stroke="${b}" stroke-width="5"/>`;if(s.shape==='bunny')extra=`<path d="M37 39Q19 2 34 8Q46 10 46 37M57 37Q64 5 77 13Q85 22 64 43" fill="${a}" stroke="#375d4a" stroke-width="3"/><path d="M34 14Q41 21 42 32M75 19Q71 26 66 35" stroke="${b}" stroke-width="5"/>`;if(s.shape==='bird')extra=`<path d="M31 43Q13 30 18 18Q38 22 45 39M61 40Q73 22 86 27Q81 45 66 51" fill="${b}" stroke="#375d4a" stroke-width="3"/><path d="m70 52 16 6-16 7" fill="#e9ad54"/>`;if(s.shape==='fish')extra=`<path d="M31 51 15 34 15 68 33 60" fill="${b}" stroke="#375d4a" stroke-width="3"/><path d="M47 40Q39 29 47 24Q57 28 54 41" fill="${b}" stroke="#375d4a" stroke-width="2"/><path d="M62 50q12 8 0 16" fill="none" stroke="#4d8793" stroke-width="3"/>`;if(s.shape==='bug')extra=`<path d="M44 38Q17 10 17 42Q22 57 43 55M57 39Q83 10 83 42Q77 57 58 55" fill="${b}" stroke="#375d4a" stroke-width="3"/><path d="M46 34 37 22M56 34 66 22" stroke="#375d4a" stroke-width="3" stroke-linecap="round"/><circle cx="30" cy="39" r="3" fill="${a}"/><circle cx="70" cy="39" r="3" fill="${a}"/>`;if(s.id==='mossling')extra+=`<path d="M48 33Q41 14 30 19Q31 34 47 39M53 32Q57 11 72 17Q70 32 55 39" fill="#98c97a" stroke="#527d55" stroke-width="2"/><path d="M31 56q-10 5-12-3" fill="none" stroke="${a}" stroke-width="8" stroke-linecap="round"/>`;if(s.id==='embercub')extra+=`<path d="M68 61q22 0 15-17q-2-9-10-9q8 11 0 13q-2-10-9-13q5 14-3 17" fill="#f2a64e" stroke="#bd7051" stroke-width="2"/>`;if(s.id==='brookfin')extra+=`<path d="M47 32Q51 17 58 28L55 36M39 64Q32 78 51 75" fill="none" stroke="#478fa7" stroke-width="3"/>`;return `<svg viewBox="0 0 100 100" role="img" aria-label="${s.name}" xmlns="http://www.w3.org/2000/svg"><ellipse cx="50" cy="87" rx="26" ry="6" fill="#55724b" opacity=".15"/>${extra}<ellipse cx="51" cy="57" rx="27" ry="26" fill="${a}" stroke="#375d4a" stroke-width="3"/><ellipse cx="50" cy="69" rx="17" ry="10" fill="${b}"/><ellipse cx="42" cy="54" rx="3.5" ry="5" fill="#243f3d"/><ellipse cx="60" cy="54" rx="3.5" ry="5" fill="#243f3d"/><circle cx="43" cy="52" r="1.2" fill="white"/><circle cx="61" cy="52" r="1.2" fill="white"/><path d="M48 64q3 3 6 0" fill="none" stroke="#654d46" stroke-width="2" stroke-linecap="round"/><circle cx="33" cy="62" r="3" fill="#ee9d8d"/><circle cx="68" cy="62" r="3" fill="#ee9d8d"/><path d="M34 77q-3 4-8 2M65 77q3 4 8 2" fill="none" stroke="#375d4a" stroke-width="3" stroke-linecap="round"/></svg>`}
+const starterIds=['mossling','embercub','brookfin'];function getSpecies(id){return species.find(s=>s.id===id)||species[0]};function makeCreature(s,level=1){return{id:s.id,name:s.name,level,maxHp:s.hp+level*3,hp:s.hp+level*3,xp:0,atk:s.atk+level*2}}
+const W=900,H=565,T=36,COLS=25,ROWS=15;const player={x:2,y:12};
+const pathTiles=new Set();function addPath(x1,y1,x2,y2){let x=x1,y=y1;for(let i=0;i<80;i++){pathTiles.add(`${x},${y}`);if(x===x2&&y===y2)break;if(x!==x2)x+=Math.sign(x2-x);else if(y!==y2)y+=Math.sign(y2-y)}}addPath(2,12,11,9);addPath(11,9,12,7);addPath(12,9,19,9);addPath(12,9,12,3);addPath(19,9,21,12);addPath(2,12,1,14);
+const grassPatches=[{x:3,y:3,w:5,h:3},{x:8,y:11,w:4,h:3},{x:17,y:11,w:5,h:3},{x:18,y:4,w:4,h:3},{x:5,y:8,w:3,h:2}];function isTall(x,y){return grassPatches.some(p=>x>=p.x&&x<p.x+p.w&&y>=p.y&&y<p.y+p.h)}
+const trees=[[1,1],[3,1],[6,1],[10,1],[14,1],[20,1],[23,1],[1,5],[10,4],[14,5],[23,7],[1,9],[3,10],[14,11],[15,12],[23,12],[6,14],[11,14],[18,14],[23,14],[8,6],[9,6],[15,8],[16,8]];
+function pondAt(x,y){return((x-20.5)/3.2)**2+((y-5.5)/2.2)**2<1}
+function blocked(x,y){return x<0||y<0||x>=COLS||y>=ROWS||trees.some(([tx,ty])=>tx===x&&ty===y)||pondAt(x,y)}
+function drawWorld(){ctx.clearRect(0,0,W,H);for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++){let n=(x*17+y*31+x*y*7)%7;ctx.fillStyle=['#a9d68f','#aed993','#a6d18b','#b0d993','#a5d18a','#acd68e','#aad48d'][n];ctx.fillRect(x*T,y*T,T,T);ctx.fillStyle='#87bc7770';ctx.fillRect(x*T,y*T+T-2,T,2);if(pathTiles.has(`${x},${y}`)){ctx.fillStyle=['#d9c99c','#d4c393','#dfd0a6'][(x+y)%3];ctx.fillRect(x*T,y*T,T,T);ctx.fillStyle='#bea97655';ctx.fillRect(x*T,y*T+T-2,T,2);if((x*3+y)%5===0){ctx.fillStyle='#b9a87577';ctx.fillRect(x*T+9,y*T+14,3,2)}}}
+// water pond
+ctx.save();ctx.fillStyle='#75c1c3';ctx.beginPath();ctx.ellipse(20.5*T+18,5.5*T+17,3.2*T,2.2*T,.08,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#e3f4d2';ctx.lineWidth=7;ctx.stroke();ctx.restore();for(let i=0;i<7;i++){let x=(18.4+(i*7%25)*.16)*T,y=(4.5+(i*13%19)*.12)*T;ctx.strokeStyle='#b5e5d7';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,y);ctx.quadraticCurveTo(x+10,y-4,x+21,y);ctx.stroke()}
+// small footbridge
+ctx.fillStyle='#aa8058';ctx.fillRect(18*T,5*T,2*T,22);for(let i=0;i<4;i++){ctx.fillStyle=i%2?'#d1a26d':'#c3915e';ctx.fillRect(18*T+i*18,5*T,13,22)}
+// tall grass
+for(const p of grassPatches){for(let y=p.y;y<p.y+p.h;y++)for(let x=p.x;x<p.x+p.w;x++){ctx.fillStyle=['#7ab66d','#82bc6e','#76b469'][(x+y)%3];ctx.fillRect(x*T,y*T,T,T);for(let j=0;j<5;j++){let bx=x*T+5+((j*11+x*7+y*13)%26),by=y*T+29-((j*7+x*3)%11);ctx.strokeStyle=['#4f965d','#5ca367','#438d57'][j%3];ctx.lineWidth=2.2;ctx.beginPath();ctx.moveTo(bx,by);ctx.quadraticCurveTo(bx-4,by-9,bx-2,by-15);ctx.moveTo(bx+1,by);ctx.quadraticCurveTo(bx+6,by-7,bx+4,by-13);ctx.stroke()}if((x+y)%4===0){ctx.fillStyle='#f8e98e';ctx.beginPath();ctx.arc(x*T+18,y*T+16,3,0,7);ctx.fill()}}}
+// decorative flowers and stones
+for(let i=0;i<44;i++){let x=(i*37+21)%COLS,y=(i*19+2)%ROWS;if(pathTiles.has(`${x},${y}`)||trees.some(t=>t[0]===x&&t[1]===y)||isTall(x,y)||pondAt(x,y))continue;let px=x*T+((i*13)%28)+4,py=y*T+((i*17)%27)+5;ctx.fillStyle=['#f8e8a2','#f1b6a5','#fff5d5','#d7c6ed'][i%4];ctx.beginPath();ctx.arc(px,py,2.4,0,7);ctx.fill();ctx.fillStyle='#e6ac65';ctx.beginPath();ctx.arc(px,py,1,0,7);ctx.fill()}
+// trees on foreground
+for(const [x,y] of trees){let px=x*T+18,py=y*T+19;ctx.fillStyle='#8c6247';ctx.fillRect(px-5,py+5,10,20);ctx.fillStyle='#5e9d65';ctx.beginPath();ctx.arc(px,py-4,19,0,7);ctx.fill();ctx.fillStyle='#70af70';ctx.beginPath();ctx.arc(px-8,py-10,13,0,7);ctx.fill();ctx.fillStyle='#8ac27b';ctx.beginPath();ctx.arc(px+7,py-11,10,0,7);ctx.fill();ctx.fillStyle='#ffffff2a';ctx.beginPath();ctx.arc(px-6,py-14,4,0,7);ctx.fill()}
+// cottage
+ctx.fillStyle='#f7e6be';ctx.fillRect(11*T+3,7*T+17,62,40);ctx.fillStyle='#bf8462';ctx.beginPath();ctx.moveTo(11*T-1,7*T+20);ctx.lineTo(12*T+18,7*T-8);ctx.lineTo(13*T+36,7*T+20);ctx.closePath();ctx.fill();ctx.fillStyle='#93b8a0';ctx.fillRect(11*T+12,7*T+27,13,13);ctx.fillRect(11*T+43,7*T+27,13,13);ctx.fillStyle='#d5b87f';ctx.fillRect(11*T+30,7*T+37,12,20);ctx.fillStyle='#fff4c6';ctx.font='10px sans-serif';ctx.fillText('✿',11*T+33,7*T+53);
+// player shadow and sprite
+const px=player.x*T+18,py=player.y*T+18;ctx.fillStyle='#416b4b55';ctx.beginPath();ctx.ellipse(px,py+11,12,5,0,0,7);ctx.fill();ctx.fillStyle='#f2bd85';ctx.beginPath();ctx.arc(px,py-5,8,0,7);ctx.fill();ctx.fillStyle='#395f4e';ctx.beginPath();ctx.arc(px,py-9,9,Math.PI,0);ctx.lineTo(px+9,py-5);ctx.lineTo(px-9,py-5);ctx.fill();ctx.fillStyle='#e88465';ctx.fillRect(px-7,py+3,14,12);ctx.fillStyle='#fff2d6';ctx.fillRect(px-5,py+14,4,4);ctx.fillRect(px+2,py+14,4,4);ctx.fillStyle='#3d5f4e';ctx.fillRect(px-10,py+3,3,8);ctx.fillRect(px+7,py+3,3,8);ctx.fillStyle='#263e39';ctx.fillRect(px-3,py-5,2,2);ctx.fillRect(px+3,py-5,2,2);
+}

