}
function renderRoster(){const root=$('#roster');if(!state.team.length){root.innerHTML='<div class="roster-empty">Your trail team is waiting.<br>Choose a companion to begin!</div>';return}root.innerHTML=state.team.map((c,i)=>{const s=getSpecies(c.id);return `<div class="creature-row ${i===state.active?'active':''}" data-index="${i}" title="Make ${c.name} your trail companion"><div class="creature-thumb">${svgCreature(s)}</div><div class="creature-info"><strong>${c.name}</strong><small>${s.type} friend</small><div class="tiny-hp"><span style="width:${Math.max(0,c.hp/c.maxHp*100)}%"></span></div></div><span class="row-level">Lv.${c.level}</span></div>`}).join('');root.querySelectorAll('.creature-row').forEach(el=>el.onclick=()=>{if(state.battle)return;state.active=Number(el.dataset.index);renderRoster();toast(`${state.team[state.active].name} is leading the way!`)})}
function renderStarter(){const box=$('#starterOptions');box.innerHTML=starterIds.map(id=>{const s=getSpecies(id);return `<button class="starter-choice" data-id="${id}"><div class="starter-art">${svgCreature(s)}</div><strong>${s.name}</strong><small>${s.desc}</small><span class="type-tag">${s.type} type</span></button>`}).join('');box.querySelectorAll('button').forEach(b=>b.onclick=()=>{const c=makeCreature(getSpecies(b.dataset.id));state.team.push(c);state.started=true;$('#starterScreen').classList.remove('show');renderRoster();updateHUD();toast(`${c.name} joined your trail team!`);drawWorld()})}
function updateHUD(){$('#podCount').textContent=state.pods;$('#pearCount').textContent=state.pears;$('#dexCount').textContent=`${state.catches} caught`;$('#questText').textContent=state.catches?`Lovely! You have befriended ${state.catches} meadow ${state.catches===1?'creature':'creatures'}. Keep exploring to meet more.`:'Wander through the tall grass and say hello to a wild creature.'}
let toastTimer;function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function move(dir){if(!state.started||state.battle)return;const d={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[dir];if(!d)return;state.player.dir=dir;const nx=player.x+d[0],ny=player.y+d[1];if(blocked(nx,ny)){drawWorld();return}player.x=nx;player.y=ny;state.steps++;if(isTall(nx,ny)){state.grassSteps++;if(state.grassSteps>1&&Math.random()<.19){drawWorld();startBattle();return}}else state.grassSteps=0;$('#sceneHint').textContent=isTall(nx,ny)?'The grass rustles nearby…':'WASD or arrow keys to explore';drawWorld()}
let lastStep=0;window.addEventListener('keydown',e=>{const keys={ArrowUp:'up',w:'up',W:'up',ArrowDown:'down',s:'down',S:'down',ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right'};if(keys[e.key]){e.preventDefault();const now=Date.now();if(now-lastStep>115){lastStep=now;move(keys[e.key])}}});document.querySelectorAll('.dpad button').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();move(b.dataset.dir)})});
function randomWild(){const pool=species.filter(s=>!starterIds.includes(s.id));const s=Math.random()<.27?getSpecies(starterIds[Math.floor(Math.random()*3)]):pool[Math.floor(Math.random()*pool.length)];const c=makeCreature(s,1+Math.floor(Math.random()*2));c.hp=c.maxHp;return c}
function startBattle(){if(state.battle||!state.team.length)return;const foe=randomWild();state.battle={foe,turn:0,log:`A wild ${foe.name} wandered over!`,busy:false};$('#battleLayer').classList.add('show');$('#sceneHint').textContent='A new friend is just a pod away!';renderBattle();}
function battleCard(c,foe=false){return `<span class="battle-level">Lv. ${c.level}</span><div class="battle-name">${c.name}</div><div class="hp-line"><span style="width:${Math.max(0,c.hp/c.maxHp*100)}%"></span></div><div class="hp-numbers">${Math.max(0,c.hp)} / ${c.maxHp} HP</div>`}
function renderBattle(){if(!state.battle)return;let c=state.team[state.active],f=state.battle.foe;$('#playerBattleCard').innerHTML=battleCard(c);$('#foeBattleCard').innerHTML=battleCard(f,true);$('#foeArt').innerHTML=svgCreature(getSpecies(f.id));$('#playerArt').innerHTML=svgCreature(getSpecies(c.id));$('#battleLog').textContent=state.battle.log;const controls=$('#battleControls');if(state.battle.busy){controls.innerHTML='<span class="action-label">One moment…</span>';return}controls.innerHTML=`<span class="action-label">Your move</span><button class="action-btn primary" data-action="tackle">🌱 Tackle</button><button class="action-btn primary" data-action="special">✨ ${getSpecies(c.id).type} burst</button><button class="action-btn capture" data-action="capture" ${state.pods<1?'disabled':''}>🔴 Pod · ${state.pods}</button><button class="action-btn" data-action="heal" ${state.pears<1||c.hp>=c.maxHp?'disabled':''}>🍐 Pear · ${state.pears}</button><button class="action-btn" data-action="run">↗ Go home</button>`;controls.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>battleAction(b.dataset.action))}
function endBattle(text){if(!state.battle)return;state.battle.log=text;state.battle.busy=true;renderBattle();setTimeout(()=>{$('#battleLayer').classList.remove('show');state.battle=null;$('#sceneHint').textContent='WASD or arrow keys to explore';updateHUD();renderRoster()},1250)}
function battleAction(action){const b=state.battle;if(!b||b.busy)return;const c=state.team[state.active],f=b.foe;if(action==='run'){endBattle('You waved goodbye and headed back to the trail.');return}if(action==='heal'){if(state.pears<=0||c.hp>=c.maxHp)return;state.pears--;const amount=Math.min(22,c.maxHp-c.hp);c.hp+=amount;b.log=`A glow pear restored ${c.name} by ${amount} HP!`;renderBattle();setTimeout(enemyTurn,700);updateHUD();return}if(action==='capture'){if(state.pods<=0)return;state.pods--;const chance=.27+.61*(1-f.hp/f.maxHp);if(Math.random()<chance){const caught={...f,hp:f.maxHp};state.team.push(caught);state.catches++;b.log=`Click! ${f.name} is happy to join your trail team!`;renderBattle();updateHUD();renderRoster();endBattle(`${f.name} joined your trail team!`);return}else{b.log=`Oh! ${f.name} wriggled out of the capture pod!`;renderBattle();setTimeout(enemyTurn,700);updateHUD();return}}
const special=action==='special';const damage=Math.max(3,Math.floor(c.atk*(special?1.38:.93)+Math.random()*4));f.hp=Math.max(0,f.hp-damage);b.log=`${c.name} used ${special?getSpecies(c.id).type+' burst':'Tackle'}! ${damage} damage!`;b.turn++;if(f.hp<=0){c.xp+=12;c.level+=c.xp>=20?1:0;c.xp=c.xp>=20?c.xp-20:c.xp;c.maxHp+=c.level>1?3:0;c.hp=Math.min(c.maxHp,c.hp+8);b.log=`${f.name} skipped away. ${c.name} gained 12 trail XP!`;renderBattle();renderRoster();endBattle(b.log);return}renderBattle();setTimeout(enemyTurn,700)}
function enemyTurn(){const b=state.battle;if(!b)return;const c=state.team[state.active],f=b.foe;if(c.hp<=0){const next=state.team.findIndex(x=>x.hp>0);if(next>=0){state.active=next;b.log=`${c.name} needs a breather. ${state.team[next].name}, you're up!`;renderBattle();renderRoster();return}else{state.team.forEach(x=>x.hp=x.maxHp);state.active=0;b.log='Everyone is safe and sound after a little rest at camp.';renderBattle();endBattle(b.log);return}}const damage=Math.max(3,Math.floor(f.atk*.65+Math.random()*4));c.hp=Math.max(0,c.hp-damage);b.log=`${f.name} gave ${c.name} a gentle bonk for ${damage}!`;renderBattle();renderRoster()}

